208	    result_v.io.enq.bits.reg_idxw := mul(0).out.bits.ctrl.reg_idxw
209	    result_v.io.enq.bits.wvd := mul(0).out.bits.ctrl.wvd
210	    result_v.io.enq.bits.wvd_mask := mul(0).out.bits.mask
211	
212	    result_x.io.enq.bits.warp_id := mul(0).out.bits.ctrl.wid
213	    result_x.io.enq.bits.reg_idxw := mul(0).out.bits.ctrl.reg_idxw
214	    result_x.io.enq.bits.wxd := mul(0).out.bits.ctrl.wxd
215	    result_x.io.enq.bits.wb_wxd_rd := mul(0).out.bits.result
216	
217	    if (SPIKE_OUTPUT) {
218	      result_v.io.enq.bits.spike_info.get := mul(0).out.bits.ctrl.spike_info.get
219	      result_x.io.enq.bits.spike_info.get := mul(0).out.bits.ctrl.spike_info.get
