328	
329	    switch(recvCS){
330	      is(0.U){
331	        when(recv.fire){
332	          when(mul(0).out.bits.ctrl.wxd){
333	            recvNS := maxIter.U
334	          }.elsewhen(mul(0).out.bits.ctrl.wvd){
335	            recvNS := 1.U
336	          }.otherwise{
337	            recvNS := 0.U
338	          }
339	        }.otherwise{
340	          recvNS := 0.U
341	        }
342	      }
343	      is((1 until maxIter).map{_.U}){
344	        when(recv.fire){
345	          recvNS := recvCS +% 1.U
346	        }.otherwise{
347	          recvNS := 0.U
348	        }
349	      }
350	      is(maxIter.U){
351	        when(outFIFOReady){
352	          when(recv.fire){
353	            when(mul(0).out.bits.ctrl.wxd){
354	              recvNS := maxIter.U
355	            }.elsewhen(mul(0).out.bits.ctrl.wvd){
356	              recvNS := 1.U
357	            }.otherwise {
358	              recvNS := 0.U
359	            }
360	          }.otherwise{
361	            recvNS := 0.U
362	          }
363	        }.otherwise{
364	          recvNS := recvCS
365	        }
366	      }
367	    }
368	
369	    switch(recvNS){
370	      is(0.U){
